const code = String($input.item.json.query || $input.item.json.code || '');

function detectLanguage(src) {
  const patterns = [
    { lang: 'python', re: /\b(def |import |elif |self\.|print\()/ },
    { lang: 'typescript', re: /\b(interface |: string|: number|export type)/ },
    { lang: 'javascript', re: /\b(function |const |let |=>|require\(|console\.log)/ },
    { lang: 'java', re: /\b(public class|private |System\.out\.println|void )/ },
    { lang: 'csharp', re: /\b(using System|namespace |public class|Console\.WriteLine)/ },
    { lang: 'go', re: /\b(func |package main|fmt\.Println)/ },
    { lang: 'rust', re: /\b(fn |impl |let mut|println!)/ },
    { lang: 'cpp', re: /\b(#include|std::|int main\()/ },
    { lang: 'ruby', re: /\b(def |end\b|puts )/ },
    { lang: 'sql', re: /\b(SELECT |FROM |WHERE )/i }
  ];
  for (const p of patterns) {
    if (p.re.test(src)) return p.lang;
  }
  return 'unknown';
}

const language = detectLanguage(code);
const lines = code.split('\n');
const totalLines = lines.length;
const blankLines = lines.filter(l => l.trim() === '').length;
const commentLines = lines.filter(l => /^\s*(#|\/\/|\/\*|\*)/.test(l)).length;
const codeLines = totalLines - blankLines - commentLines;

const funcPatterns = [
  /\bdef\s+([a-zA-Z_][\w]*)\s*\(/g,
  /\bfunction\s+([a-zA-Z_][\w]*)\s*\(/g,
  /\bfn\s+([a-zA-Z_][\w]*)\s*\(/g,
  /\bfunc\s+([a-zA-Z_][\w]*)\s*\(/g,
  /\b(?:public|private|protected|static)?\s*(?:[\w<>\[\]]+\s+)?([a-zA-Z_][\w]*)\s*\([^)]*\)\s*\{/g
];
const reservedWords = new Set(['if', 'for', 'while', 'switch', 'catch']);
const functionNames = new Set();
for (const re of funcPatterns) {
  let m;
  while ((m = re.exec(code)) !== null) {
    if (m[1] && !reservedWords.has(m[1])) functionNames.add(m[1]);
  }
}

const branchKeywords = /\b(if|else if|elif|for|while|case|catch|except)\b|&&|\|\|/g;
const branchMatches = code.match(branchKeywords) || [];
const approxComplexity = 1 + branchMatches.length;

return JSON.stringify({
  language,
  totalLines,
  codeLines,
  commentLines,
  blankLines,
  functionNames: [...functionNames],
  approxComplexity
});

